from pathlib import Path

root=Path('apps/painel-ldr/src')

# 1) Subscription backend: exact 50% first invoice for 24h; normal recurring price after.
p=root/'lib/library-subscription.server.ts'
t=p.read_text()
old='''const PRICE_BRL = 3990;\nconst PRICE_EUR = 990;\nconst PRODUCT_NAME = "Biblioteca LDR — Assinatura Mensal";'''
new='''const PRICE_BRL = 3990;\nconst PRICE_EUR = 990;\nconst PROMO_FIRST_BRL = 1995;\nconst PROMO_FIRST_EUR = 495;\nconst PROMO_END_AT = "2026-09-12T16:46:00.000Z";\nconst PRODUCT_NAME = "Biblioteca LDR — Assinatura Mensal";\nfunction libraryPromoActive(){ return Date.now() < Date.parse(PROMO_END_AT); }'''
assert old in t, 'subscription constants anchor missing'
t=t.replace(old,new,1)
old='''  return { customer, subscription, active: accessActive(subscription?.status), priceBrlCents: PRICE_BRL, priceEurCents: PRICE_EUR };'''
new='''  return { customer, subscription, active: accessActive(subscription?.status), priceBrlCents: PRICE_BRL, priceEurCents: PRICE_EUR, promoActive: libraryPromoActive(), promoEndsAt: PROMO_END_AT, promoFirstBrlCents: PROMO_FIRST_BRL, promoFirstEurCents: PROMO_FIRST_EUR };'''
assert old in t, 'context return anchor missing'
t=t.replace(old,new,1)
old='''  params.set("line_items[0][quantity]", "1");\n  params.set("success_url", `${appOrigin()}/cliente/biblioteca?subscription=success&session_id={CHECKOUT_SESSION_ID}`);'''
new='''  params.set("line_items[0][quantity]", "1");\n  if (libraryPromoActive()) {\n    const couponParams = new URLSearchParams();\n    couponParams.set("duration", "once");\n    couponParams.set("percent_off", "50");\n    couponParams.set("name", "Biblioteca LDR — 50% primeiro mês — 24h");\n    const couponResponse = await fetch("https://api.stripe.com/v1/coupons", { method: "POST", headers: { Authorization: `Bearer ${secret}`, "Content-Type": "application/x-www-form-urlencoded" }, body: couponParams });\n    const coupon = await couponResponse.json() as { id?: string; error?: { message?: string } };\n    if (!couponResponse.ok || !coupon.id) { await db.from("library_subscriptions").delete().eq("id", row.id); fail(coupon.error?.message || "Não foi possível aplicar a promoção de 50%."); }\n    params.set("discounts[0][coupon]", coupon.id);\n    params.set("metadata[promotion]", "library_50_first_month_24h");\n    params.set("subscription_data[metadata][promotion]", "library_50_first_month_24h");\n  }\n  params.set("success_url", `${appOrigin()}/cliente/biblioteca?subscription=success&session_id={CHECKOUT_SESSION_ID}`);'''
assert old in t, 'checkout anchor missing'
t=t.replace(old,new,1)
p.write_text(t)

# 2) Library UI: promotion card inside Biblioteca, normal price from second month.
p=root/'routes/_clientarea.cliente.biblioteca.tsx'
t=p.read_text()
old='''<p className="text-xs text-white/70">{subscriptionData?.active?SUB_TXT[locale].active:SUB_TXT[locale].title}</p><p className="mt-1 text-2xl font-black text-[#f2cf83]">{market==="BR"?money(subscriptionData?.priceBrlCents??3990,"BRL",locale):money(subscriptionData?.priceEurCents??990,"EUR",locale)}<span className="text-xs font-medium text-white/65"> / mês</span></p>{subscriptionData?.active?'''
new='''<p className="text-xs text-white/70">{subscriptionData?.active?SUB_TXT[locale].active:subscriptionData?.promoActive?(locale==="pt"?"PROMOÇÃO 24H · 50% OFF NO 1º MÊS":locale==="fr"?"PROMO 24H · -50% LE 1ER MOIS":locale==="es"?"PROMO 24H · 50% EN EL 1ER MES":"24H PROMO · 50% OFF FIRST MONTH"):SUB_TXT[locale].title}</p>{!subscriptionData?.active&&subscriptionData?.promoActive?<><p className="mt-2 text-xs text-white/55 line-through">{market==="BR"?money(subscriptionData?.priceBrlCents??3990,"BRL",locale):money(subscriptionData?.priceEurCents??990,"EUR",locale)} / mês</p><p className="mt-1 text-3xl font-black text-[#ffd84d]">{market==="BR"?money(subscriptionData?.promoFirstBrlCents??1995,"BRL",locale):money(subscriptionData?.promoFirstEurCents??495,"EUR",locale)}<span className="text-xs font-medium text-white/70"> / primeiro mês</span></p><p className="mt-2 text-xs font-bold text-white/80">{locale==="pt"?"A partir do 2º mês: ":locale==="fr"?"À partir du 2e mois : ":locale==="es"?"Desde el 2º mes: ":"From month 2: "}{market==="BR"?money(subscriptionData?.priceBrlCents??3990,"BRL",locale):money(subscriptionData?.priceEurCents??990,"EUR",locale)} / mês</p></>:<p className="mt-1 text-2xl font-black text-[#f2cf83]">{market==="BR"?money(subscriptionData?.priceBrlCents??3990,"BRL",locale):money(subscriptionData?.priceEurCents??990,"EUR",locale)}<span className="text-xs font-medium text-white/65"> / mês</span></p>}{subscriptionData?.active?'''
assert old in t, 'library price UI anchor missing'
t=t.replace(old,new,1)
p.write_text(t)

# 3) Homepage sales page: reference all current courses/formations + subscription promo.
